-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Marktmechanismen > Wettbewerb
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beeinflusst der Wettbewerb die Preise für IT-Dienstleistungen eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Wettbewerb drückt Preise durch Konkurrenz"}, {"text": "Nein", "correct": false, "because": "Wettbewerb wirkt auf Preise"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch hohe Qualität im Wettbewerb Vorteile erlangen?', 2, '[{"text": "Ja", "correct": true, "because": "Qualität hebt sich im Wettbewerb ab"}, {"text": "Nein", "correct": false, "because": "Qualität ist ein Wettbewerbsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Führt starker Wettbewerb zu Innovationen in der IT-Branche?', 2, '[{"text": "Ja", "correct": true, "because": "Wettbewerb fördert Innovation"}, {"text": "Nein", "correct": false, "because": "Innovation ist oft wettbewerbsgetrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Wettbewerb in der IT-Branche unabhängig von der Anzahl der Anbieter?', 2, '[{"text": "Nein", "correct": true, "because": "Mehr Anbieter erhöhen den Wettbewerb"}, {"text": "Ja", "correct": false, "because": "Anbieterzahl beeinflusst den Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Monopol den Wettbewerb in der IT-Branche verringern?', 2, '[{"text": "Ja", "correct": true, "because": "Monopole reduzieren Konkurrenz"}, {"text": "Nein", "correct": false, "because": "Monopole schränken Wettbewerb ein"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was beschreibt den Wettbewerb in der IT-Branche am besten?', 2, '[{"text": "Konkurrenz zwischen Anbietern", "correct": true, "because": "Wettbewerb ist die Rivalität zwischen Firmen"}, {"text": "Preisstabilität", "correct": false, "because": "Wettbewerb beeinflusst Preise"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Indirekt, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor stärkt den Wettbewerb für einen IT-Betrieb am meisten?', 3, '[{"text": "Viele Anbieter", "correct": true, "because": "Mehr Anbieter erhöhen den Wettbewerb"}, {"text": "Hohe Preise", "correct": false, "because": "Preise sind Folge, kein Faktor"}, {"text": "Wenig Nachfrage", "correct": false, "because": "Nachfrage beeinflusst, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein typisches Ergebnis von starkem Wettbewerb in der IT-Branche?', 3, '[{"text": "Niedrigere Preise", "correct": true, "because": "Wettbewerb drückt Preise"}, {"text": "Höhere Gewinne", "correct": false, "because": "Gewinne sinken oft"}, {"text": "Weniger Qualität", "correct": false, "because": "Qualität kann steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Marktform zeigt den geringsten Wettbewerb für einen IT-Betrieb?', 2, '[{"text": "Monopol", "correct": true, "because": "Monopol hat keine Konkurrenz"}, {"text": "Oligopol", "correct": false, "because": "Wenige Anbieter, aber Wettbewerb"}, {"text": "Vollkommener Wettbewerb", "correct": false, "because": "Hoher Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie kann ein IT-Betrieb im Wettbewerb bestehen?', 3, '[{"text": "Durch Differenzierung der Dienstleistungen", "correct": true, "because": "Differenzierung schafft Vorteile"}, {"text": "Durch höhere Preise", "correct": false, "because": "Kann Kunden abschrecken"}, {"text": "Durch weniger Innovation", "correct": false, "because": "Innovation stärkt Wettbewerb"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern den Wettbewerb in der IT-Branche?', 4, '[{"text": "Viele Anbieter", "correct": true, "because": "Mehr Anbieter erhöhen Konkurrenz"}, {"text": "Innovationen", "correct": true, "because": "Innovation treibt Wettbewerb"}, {"text": "Niedrige Preise", "correct": true, "because": "Preiskampf verstärkt Wettbewerb"}, {"text": "Hohe Produktionskosten", "correct": false, "because": "Kosten hemmen Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat starker Wettbewerb auf einen IT-Betrieb?', 3, '[{"text": "Niedrigere Preise", "correct": true, "because": "Wettbewerb drückt Preise"}, {"text": "Höhere Qualität", "correct": true, "because": "Anbieter verbessern Angebote"}, {"text": "Weniger Innovation", "correct": false, "because": "Wettbewerb fördert Innovation"}, {"text": "Gesteigerte Effizienz", "correct": true, "because": "Wettbewerb zwingt zu Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strategien kann ein IT-Betrieb im Wettbewerb einsetzen?', 4, '[{"text": "Preisreduktion", "correct": true, "because": "Preiskampf lockt Kunden"}, {"text": "Qualitätsverbesserung", "correct": true, "because": "Qualität hebt ab"}, {"text": "Weniger Marketing", "correct": false, "because": "Marketing stärkt Wettbewerb"}, {"text": "Produktinnovation", "correct": true, "because": "Innovation schafft Vorteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Marktformen zeigen Wettbewerb in der IT-Branche?', 3, '[{"text": "Vollkommener Wettbewerb", "correct": true, "because": "Viele Anbieter, hoher Wettbewerb"}, {"text": "Oligopol", "correct": true, "because": "Wenige Anbieter, aber Wettbewerb"}, {"text": "Monopol", "correct": false, "because": "Kein Wettbewerb"}, {"text": "Monopolistischer Wettbewerb", "correct": true, "because": "Viele Anbieter mit Differenzierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann den Wettbewerb in der IT-Branche verringern?', 3, '[{"text": "Monopolbildung", "correct": true, "because": "Monopole eliminieren Konkurrenz"}, {"text": "Markteintrittsbarrieren", "correct": true, "because": "Barrieren schränken Anbieter ein"}, {"text": "Niedrige Preise", "correct": false, "because": "Preise fördern Wettbewerb"}, {"text": "Marktzugangskontrolle", "correct": true, "because": "Beschränkungen reduzieren Wettbewerb"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Wettbewerb führt zu niedrigeren Preisen in der IT-Branche. b) Wettbewerb hat keinen Einfluss auf die Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preise ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Viele Anbieter erhöhen den Wettbewerb in der IT-Branche. b) Innovationen fördern den Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Anbieterzahl und Innovation fördern Wettbewerb"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Monopol reduziert den Wettbewerb in der IT-Branche. b) Wettbewerb führt immer zu höheren Preisen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Monopol ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Qualitätsverbesserung stärkt den Wettbewerb eines IT-Betriebs. b) Weniger Anbieter fördern den Wettbewerb.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Wettbewerb kann die Effizienz eines IT-Betriebs steigern. b) Ein Oligopol schließt Wettbewerb aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

